//! Raw bindings to libghostty-vt (Ghostty's terminal engine), generated by
//! `build.rs` from the headers of the pinned `third_party/ghostty` checkout.
//! Perchd's `screen` module is the only safe wrapper.

#![allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    clippy::all
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
